%[text] # Particle System Animation (Live Script)
%[text] This live-style script animates a simple 2D particle system with trails and optional GIF export.
%[text] Adjust parameters in the **Parameters** section and re-run subsequent sections.
%[text] *Inspired by structuring approaches from AI coding prompt collections (matlab/prompts).*

%[text] ## Parameters
%[text] You can convert key variables below to Live Script controls for interactive experimentation.

numParticles = 50;          % Number of particles (try 10–500)
numFrames    = 500;         % Total animation frames
trailLength  = 20;          % Length of each particle trail
stepScale    = 0.20;        % Random walk step scale
enableGIF    = true;        % Toggle GIF export on/off
writeEveryN  = 10;          % Write every Nth frame to GIF
gifFilename  = "particle_animation.gif"; % Output GIF filename
gifDelayTime = 0.06;        % Delay (s) between GIF frames
rng(0);                     % For reproducibility; remove for variability

%[text] ## Initialization
%[text] Allocate position history: `positions(particle, xy, trailIndex)`

positions = zeros(numParticles, 2, trailLength);
positions(:,:,1) = 10 * (rand(numParticles,2) - 0.5); % Initial positions

%[text] ### Figure & Axes Setup

fig = figure('Position',[100 100 800 600],'Color','k'); %[output:2e8e3fcf]
ax = axes(fig); %[output:2e8e3fcf]
ax.XLim = [-10 10]; %[output:2e8e3fcf]
ax.YLim = [-10 10]; %[output:2e8e3fcf]
axis(ax,'off'); %[output:2e8e3fcf]
title(ax,'Particle System Animation','Color',[0.9 0.9 0.9]); %[output:2e8e3fcf]

%[text] ### Particle Scatter
%[text] Created once for efficiency.

hParticles = scatter(ax, positions(:,1,1), positions(:,2,1), 50, ... %[output:2e8e3fcf]
    (1:numParticles)', 'filled'); %[output:2e8e3fcf]
colormap(ax, parula(numParticles)); %[output:2e8e3fcf]
cb = colorbar(ax); cb.Color = [0.8 0.8 0.8]; %[output:2e8e3fcf]

%[text] ### Trail Line Objects
%[text] Pre-created for efficiency.

hTrails = gobjects(numParticles,1);
for p = 1:numParticles
    hTrails(p) = line(ax, NaN(1,trailLength), NaN(1,trailLength), ... %[output:2e8e3fcf]
        'Color',[0.7 0.7 0.7], 'LineWidth',1); %[output:2e8e3fcf]
end
drawnow; % Initial render

%[text] Preallocate helper for GIF (initialized later if enabled)
gifInitialized = false;

%[text] ## Animation Loop
%[text] The loop updates the head position via a random walk, shifts the trail history, updates graphics objects, and optionally writes GIF frames.

for frame = 1:numFrames %[output:group:4b842dcf]
    % Random walk step
    newPositions = positions(:,:,1) + stepScale * randn(numParticles,2);

    % Shift trail history (move older entries one index down)
    positions(:,:,2:end) = positions(:,:,1:end-1);
    positions(:,:,1) = newPositions;

    % Update particle head positions
    hParticles.XData = positions(:,1,1); %[output:2e8e3fcf]
    hParticles.YData = positions(:,2,1);

    % Update trails efficiently
    for p = 1:numParticles
        hTrails(p).XData = positions(p,1,:);
        hTrails(p).YData = positions(p,2,:);
    end

    % Throttled rendering
    drawnow limitrate

    % Optional GIF writing
    if enableGIF && mod(frame, writeEveryN) == 0
        frameData = getframe(ax);
        [imind, cm] = rgb2ind(frameData.cdata, 256);
        if ~gifInitialized
            imwrite(imind, cm, gifFilename, 'gif', 'Loopcount', inf, ...
                'DelayTime', gifDelayTime);
            gifInitialized = true;
        else
            imwrite(imind, cm, gifFilename, 'gif', 'WriteMode', 'append', ...
                'DelayTime', gifDelayTime);
        end
    end
end %[output:group:4b842dcf]

%[text] ## Post-Run Summary
%[text] Display a brief summary of run parameters and output artifacts.

runInfo.numParticles = numParticles;
runInfo.numFrames    = numFrames;
runInfo.trailLength  = trailLength;
runInfo.gifWritten   = enableGIF;
if enableGIF
    runInfo.gifFilename = gifFilename;
end
disp(runInfo); %[output:211264d5]

%[text] ## Experiment Ideas

%[text] ## Cleanup (Optional)
%[text] Uncomment to close the figure automatically after animation.
% close(fig);

